for c,n in [("umami-acsd003a419","umami-acsd003a419"),("alcove-site","alcove-site")]:
    ecs.update_service(cluster=c, service=n, desiredCount=1)
tgs={n: elb.describe_target_groups(Names=[n])["TargetGroups"][0]["TargetGroupArn"] for n in ("umami-acsd003a419","alcove-site")}
for i in range(60):
    state={}
    for n,arn in tgs.items():
        th=elb.describe_target_health(TargetGroupArn=arn)["TargetHealthDescriptions"]
        state[n]=[x["TargetHealth"]["State"] for x in th]
    print(" ", i*15, state, flush=True)
    if all(v==["healthy"] for v in state.values()):
        print("  BOTH HEALTHY"); break
    time.sleep(15)
EOF

